const input = (
  $input.first().json.chatInput ||
  $input.first().json.query?.prompt ||
  ''
).toString().trim();

const lower = input.toLowerCase();

const greetings = ['hi','hello','hey','thanks','thank you','ok','okay','bye','sup','yo','howdy','good morning','good evening','good afternoon','what can you do','who are you'];
const isGreeting = greetings.some(g => lower === g || lower === g + '!' || lower === g + '.');
const isTooShort = input.length < 15;
const hasWebsiteKeywords = /(website|site|page|landing|portfolio|app|blog|shop|store|brand|company|business|product|agency|studio|platform|startup|saas|firm|practice|restaurant|hotel|clinic|gym|salon)/i.test(input);

const intent = (isGreeting || (isTooShort && !hasWebsiteKeywords)) ? 'other' : 'build';

return [{
  json: {
    ...$input.first().json,
    raw_input: input,
    intent
  }
}];

const rawPrompt = (
  $input.first().json.chatInput ||
  $input.first().json.raw_input ||
  ''
).toString().trim();

if (!rawPrompt) {
  throw new Error('Missing required parameter: prompt');
}
if (rawPrompt.length > 2000) {
  throw new Error('Prompt too long (max 2000 chars)');
}

const directions = [
  {
    name: 'editorial',
    description: 'Editorial magazine aesthetic — large serif display headings (Playfair Display, Fraunces, or Instrument Serif), generous whitespace, asymmetric grid, muted earth-tone palette, restrained use of color.'
  },
  {
    name: 'brutalist-modern',
    description: 'Refined brutalism — oversized sans-serif typography (Inter, Space Grotesk), high contrast monochrome with one accent color, hard edges, intentionally raw layout, subtle grain or noise textures.'
  },
  {
    name: 'soft-luxury',
    description: 'Soft luxury — cream/off-white backgrounds, deep emerald or burgundy accents, elegant serif/sans pairing, soft shadows, rounded corners, tasteful use of gold or sage, photography-forward.'
  },
  {
    name: 'tech-minimal',
    description: 'Tech minimal — true black or near-black background, thin geometric sans-serif (Geist, Inter), single neon accent (electric blue, lime, or violet), micro-animations implied through transitions, dense information hierarchy.'
  },
  {
    name: 'warm-handcrafted',
    description: 'Warm handcrafted — beige and terracotta palette, friendly humanist typography, organic shapes, subtle textures, generous line-height, conversational copy tone.'
  },
  {
    name: 'gradient-vibrant',
    description: 'Vibrant gradient — bold mesh gradients, glassmorphism cards, modern geometric sans, animated-feel layouts using CSS transforms, high-energy color story (magenta/cyan, orange/pink, lime/teal).'
  }
];

const direction = directions[Math.floor(Math.random() * directions.length)];

return [{
  json: {
    user_prompt: rawPrompt,
    direction: direction.name,
    direction_brief: direction.description,
    received_at: new Date().toISOString()
  }
}];

const raw = $input.first().json;
const content = raw?.choices?.[0]?.message?.content;
if (!content) throw new Error('OpenAI returned empty content');

const spec = typeof content === 'string' ? JSON.parse(content) : content;
let html = spec.html || '';

if (!/<!DOCTYPE\s+html/i.test(html)) throw new Error('HTML missing DOCTYPE');
if (!/<\/html>/i.test(html)) throw new Error('HTML not closed');
if (html.length < 500) throw new Error('HTML suspiciously short — likely truncated');

if (!/cdn\.tailwindcss\.com/.test(html)) {
  html = html.replace(/<\/head>/i, '  <script src="https://cdn.tailwindcss.com"></script>\n</head>');
}

if (!/name=["']viewport["']/.test(html)) {
  html = html.replace(/<head>/i, '<head>\n  <meta name="viewport" content="width=device-width, initial-scale=1">');
}

return [{
  json: {
    title: spec.title,
    description: spec.description,
    html,
    direction: $('Prompt Refiner').first().json.direction,
    user_prompt: $('Prompt Refiner').first().json.user_prompt
  }
}];

const { html } = $input.first().json;

// Normalize double-encoded \n literals → real newlines → strip entirely
// HTML renders identically without newlines
const cleanHtml = html
  .replace(/\\n/g, '\n')
  .replace(/\n/g, '');

return [{
  json: {
    output: cleanHtml
  }
}];

return [{
  json: {
    output: "I generate complete websites from a description. Try something like:

• *A bold landing page for a Japanese whisky brand*
• *Portfolio site for a freelance photographer based in London*
• *E-commerce homepage for a sustainable skincare brand*
• *SaaS product page for an AI scheduling tool*

Describe your website and I'll build it."
  }
}];

const { user_prompt, direction, direction_brief, imageUrls } = $input.first().json;

const imageBlock = imageUrls?.length
  ? `\n\nREAL IMAGES — use ONLY these exact Pexels URLs in <img> tags (do not invent any other URLs):\n${imageUrls.map((u, i) => `${i + 1}. ${u}`).join('\n')}`
  : '';

const systemPrompt = `You are a world-class web designer and front-end engineer — the kind whose work wins Awwwards and gets featured on Sites of the Day. You ship websites that feel intentional, not generic.

NON-NEGOTIABLES:
- Accent color must be sophisticated and easy on the eye — deep tones only (forest green, navy, slate blue, warm burgundy, dusty rose, muted teal). Never use bright red, bright orange, or high-saturation colors as the primary accent.
- When a section has a colored background, always use white or off-white text and verify it has sufficient contrast. Never place white text on a light-colored background. Never place dark text on a dark background.
- Faithful to the user's prompt. Every section must serve their stated brief.
- Real, specific, evocative copy. NEVER use Lorem ipsum or filler. Write copy as if you understand the brand.
- Strong typographic hierarchy — at least one display-scale heading (text-6xl+ on desktop), clear secondary scale, well-leaded body text.
- Considered color palette — exactly 1 background, 1 foreground, 1 accent, 1 muted. No fifth color.
- Real layout craft — asymmetry, intentional whitespace, varied section rhythms.
- Mobile-first responsive using Tailwind sm:/md:/lg: prefixes.
- Accessible semantic HTML5 with descriptive alt text and sufficient color contrast.

VISUAL TOOLBOX:
- Google Fonts via link in head. Pair fonts thoughtfully (Fraunces + Inter, Playfair + Manrope, etc).
- Tailwind CSS via https://cdn.tailwindcss.com
- Inline SVG for logos, icons, decorative shapes.
- Subtle CSS gradients, mesh effects, grain via SVG noise filters.
- Hover states, smooth transitions (transition-all duration-300).
- If real image URLs are provided below, use ONLY those exact URLs in <img> tags. Use each one at most once.

FORBIDDEN — STRICT RULES, NO EXCEPTIONS:
- NEVER use local or relative image paths like /images/*, ./images/*, images/*.jpg, or any src that does not start with https://
- NEVER invent or fabricate image URLs. If no real URL is available for a slot, use a CSS gradient + SVG instead.
- NEVER use placeholder services: no picsum, no loremflickr, no unsplash, no placehold.it, no via.placeholder.com.
- Every image slot MUST either use a provided https:// Pexels URL or be replaced with a div using CSS gradient + inline SVG icon. Zero broken images is non-negotiable.
- Generic phrases: innovative solutions, cutting-edge, leverage synergies.
- Default purple-to-blue gradients unless the brief calls for it.
- External JavaScript beyond Tailwind CDN.
- Placeholder URLs — use plausible brand-matching domains.

OUTPUT: one complete valid HTML5 document, DOCTYPE through closing html tag. Tailwind via CDN. No build step required.`;

const userContent = `BRIEF:\n${user_prompt}\n\nDESIGN DIRECTION: ${direction}\n${direction_brief}${imageBlock}\n\nBuild it. Make it the best version of itself — confident, specific, shaped by the brief. Surprise me with one detail I would not have asked for but will love when I see it.`;

const payload = {
  model: 'gpt-4o-2024-08-06',
  temperature: 0.85,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent }
  ],
  response_format: {
    type: 'json_schema',
    json_schema: {
      name: 'website',
      strict: true,
      schema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Page title — brand name and short tagline' },
          description: { type: 'string', description: 'Meta description 140-160 chars' },
          html: { type: 'string', description: 'Complete HTML5 document from DOCTYPE to closing html tag' }
        },
        required: ['title', 'description', 'html'],
        additionalProperties: false
      }
    }
  }
};

return [{
  json: {
    ...$input.first().json,
    requestPayload: JSON.stringify(payload)
  }
}];

const pexelsData = $input.first().json;
const photos = pexelsData.photos || [];
const imageUrls = photos
  .map(p => p.src?.large || p.src?.medium)
  .filter(Boolean)
  .slice(0, 6);

const refiner = $('Prompt Refiner').first().json;
const bodyCode = $('Build Request Body Code').first().json;

return [{
  json: {
    ...refiner,
    ...bodyCode,
    imageUrls
  }
}];
